import logging
import re
from robot.utils.robottime import timestr_to_secs
from taf.ul.power_ue.exception import SyslogNotCollected
from taf.ul.stream.aasyslog.facade import AasyslogThroughput
from taf.ul.power_ue.store import DTvsLOG


class Aasyslog(object):
    def __init__(self, tl, robot_logs_dir):
        self.logger = logging.getLogger("power_ue")
        self.tl = tl
        self.robot_logs_dir = robot_logs_dir
        self._aasyslog = AasyslogThroughput()
        self.dtvslog = DTvsLOG()
        self.dtvslog.init_store()

    def collect(
        self,
        omit=60,
        end=660,
        gnb_index=0,
        du_index=0,
        common_unit_index=0,
        stop_after_duration=True,
        alias="syslog_0",
        **kwargs,
    ):
        """
        Collect throughput for given duration.

        :param omit: it is a delay in seconds to start counting the tput ex.
                     '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex.
                    '40' - it takes into account data till 40 second of transfer.
        :param gnb_index: Optional[str], gnb index in tl to collect log.
        :param du_index: Optional[str], du index in gnb to collect log.
        :param common_unit_index: Optional[str], common unit index in du to collect log.
        :param stop_after_duration: Optional[bool], if teardown after duration. E.G True / False.
        :param alias: Optional[str], alias of collected log info.
        :return: dict, {"log_path": log_path, "omit": omit, "end": end}
        """
        if isinstance(omit, str):
            omit = timestr_to_secs(omit)
        if isinstance(end, str):
            end = timestr_to_secs(end)
        host, username, password = self._get_host_information(
            gnb_index=gnb_index, du_index=du_index, common_unit_index=common_unit_index
        )
        log_path = self._aasyslog.collect_aasyslog_throughput(
            host=host,
            username=username,
            password=password,
            local_output_dir=self.robot_logs_dir,
            omit=omit,
            end=end,
            stop_after_duration=stop_after_duration,
        )
        self.dtvslog.store_log(alias, log_path, omit, end)
        return {"log_path": [log_path], "omit": omit, "end": end, "alias": alias}

    def check_unidirectional_throughput(
        self,
        direction,
        theoretical_throughput,
        average_tolerance=0.95,
        minimum_tolerance=0.8,
        nrcellids=None,
        ca=False,
        enable_chart_generation=True,
        customized_chart_file_name="",
        alias="syslog_0",
        **kwargs,
    ):
        log_details = self.dtvslog.get_log(alias)
        if not log_details:
            raise SyslogNotCollected(
                "Failed to find log with alias {}, Please execute collect before check.".format(
                    alias
                )
            )
        return self._aasyslog.check_aasyslog_throughput(
            direction=direction,
            log_path=log_details["log_path"],
            local_output_dir=self.robot_logs_dir,
            cells=nrcellids,
            theoretical_throughput=theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            ca=ca,
            enable_chart_generation=enable_chart_generation,
            customized_chart_file_name=customized_chart_file_name,
        )

    def check_bidirectional_throughput(
        self,
        ul_theoretical_throughput,
        dl_theoretical_throughput,
        average_tolerance=0.95,
        minimum_tolerance=0.8,
        nrcellids=None,
        ca=False,
        enable_chart_generation=True,
        customized_chart_file_name="",
        alias="syslog_0",
        **kwargs,
    ):
        average_tolerance = self._get_tolerance_decimal(tolerance=average_tolerance)
        minimum_tolerance = self._get_tolerance_decimal(tolerance=minimum_tolerance)
        log_details = self.dtvslog.get_log(alias)
        if not log_details:
            raise SyslogNotCollected(
                "Failed to find log with alias {}, Please execute collect before check.".format(
                    alias
                )
            )
        return self._aasyslog.check_bi_aasyslog_throughput(
            log_path=log_details["log_path"],
            local_output_dir=self.robot_logs_dir,
            cells=nrcellids,
            ul_theoretical_throughput=ul_theoretical_throughput,
            dl_theoretical_throughput=dl_theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            ca=ca,
            enable_chart_generation=enable_chart_generation,
            customized_chart_file_name=customized_chart_file_name,
        )

    def _get_host_information(self, gnb_index, du_index, common_unit_index):
        host = self.tl.gnbs[gnb_index].dus[du_index].f1_m_ip_addr
        if not host:
            host = (
                self.tl.gnbs[gnb_index]
                .dus[du_index]
                .airscale.common_units[common_unit_index]
                .lmp_connection.addr
            )
        username = (
            self.tl.gnbs[gnb_index]
            .dus[du_index]
            .airscale.common_units[common_unit_index]
            .lmp_connection.username
        )
        password = (
            self.tl.gnbs[gnb_index]
            .dus[du_index]
            .airscale.common_units[common_unit_index]
            .lmp_connection.password
        )
        return host, username, password

    @staticmethod
    def _get_tolerance_decimal(tolerance):
        tolerance = str(tolerance)
        tolerance_num = re.search(r"\d+\.?\d*", tolerance).group()
        tolerance = (
            float(tolerance) if "%" not in tolerance else float(tolerance_num) / 100
        )
        return tolerance
